            Describe.Lean(DescribeId.Create("weighted-empirical-measure"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.weightedEmpirical"), H("Location-weighted empirical measure"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Each sampled location contributes its nonnegative part as the weight of a Dirac atom."))), DescribeRole.Definition),
