            Describe.Lean(DescribeId.Create("capped-dyadic-intensity"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.cappedDyadicIntensity"), H("Finite dyadic intensity"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Restrict the reciprocal-location density to one dyadic interval and to the positive cutoff interval. Each band has finite intensity."))), DescribeRole.Definition),
