            Describe.Lean(DescribeId.Create("poisson-mixture-integral"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.lintegral_finitePoissonLaw_normalized"), H("Integrate over count and locations"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A measurable nonnegative observable of the Poisson measure is integrated by first conditioning on the count and then using its finite product law."))), DescribeRole.Theorem),
