            Describe.Lean(DescribeId.Create("poisson-successor-recurrence"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.poisson_singleton_succ"), H("Poisson mass recurrence"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The successor factorial identity supplies the exact recurrence used to sum the Poisson expectation."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("poisson-count-expectation"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.lintegral_poisson_id"), H("Expected Poisson count"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The nonnegative integral of the count equals its intensity parameter."))), DescribeRole.Theorem),
