            Describe.Lean(DescribeId.Create("band-sum-measurability"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.measurable_fragment_sum"), H("Measurability of the countable measure sum"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Evaluating the sum on a measurable set is a measurable countable sum."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-fragments-measurability"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.measurable_finiteFragments"), H("Measurability of the finite realization"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The finite-measure branch and zero fallback combine over a measurable finiteness predicate."))), DescribeRole.Theorem),
