            Describe.Lean(DescribeId.Create("recover-capped-intensity"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.sum_cappedDyadicIntensity"), H("Reassemble the original intensity"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The disjoint restrictions sum to the reciprocal-location intensity on the cutoff interval."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("countable-fragment-first-moment"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.lintegral_fragment_sum"), H("First moment before imposing finiteness"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Nonnegative integration exchanges the band sum and expectation. Multiplication by the location cancels the reciprocal-location density."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("almost-sure-finite-fragment-mass"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.ae_isFiniteMeasure_fragment_sum"), H("The total fragment mass is almost surely finite"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The first moment of total mass is finite, so the countable measure sum is finite almost surely. The conclusion is proved before using the finite-measure fallback."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("fragment-law-probability"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.fragmentLaw_isProbabilityMeasure"), H("The fragment law is a probability measure"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The completed measurable pushforward is a probability measure for every real cutoff."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("fragment-law-first-moment"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.lintegral_fragmentLaw"), H("First moment on the actual fragment law"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every measurable nonnegative test, the expected fragment integral equals its Lebesgue integral over the cutoff interval."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("small-fragment-mass-tail"), DeclarationHandle.Create("D5/S3/PrimeGaps/FragmentLaw.fragmentLaw_small_seed_tail"), H("Tail probability of deleted small-fragment mass"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For a positive cutoff and threshold and a nonnegative deletion scale, Markov's inequality bounds the deletion event by the minimum of the two cutoffs divided by the threshold. This leaves discontinuous mesh-boundary effects for the next module."))), DescribeRole.Theorem)
        )));
